const { DatabaseSync } = await import('node:sqlite');
const db = new DatabaseSync(':memory:');
db.exec(`
  CREATE TABLE docs (id INTEGER PRIMARY KEY, title TEXT NOT NULL, version INTEGER NOT NULL);
  INSERT INTO docs (id, title, version) VALUES (1, 'Draft', 1), (2, 'Other', 7);
`);
assert.equal(typeof mod.updateTitle, 'function', 'export function updateTitle');
const doc = (id) => ({ ...db.prepare('SELECT title, version FROM docs WHERE id = ?').get(id) });
// a handle that lets another writer commit right after your first read, as a concurrent request would
let slippedIn = false;
const racing = {
  exec: (sql) => db.exec(sql),
  prepare(sql) {
    const statement = db.prepare(sql);
    const afterRead = (rows) => {
      if (!slippedIn && /^\s*select/i.test(sql)) {
        slippedIn = true;
        db.exec("UPDATE docs SET title = 'Theirs', version = version + 1 WHERE id = 1");
      }
      return rows;
    };
    return {
      run: (...params) => statement.run(...params),
      get: (...params) => afterRead(statement.get(...params)),
      all: (...params) => afterRead(statement.all(...params)),
    };
  },
};
const result = mod.updateTitle(racing, 1, 'Mine', 1);
if (slippedIn) {
  assert.deepEqual(result, { status: 'conflict', version: 2 });
  assert.deepEqual(doc(1), { title: 'Theirs', version: 2 });
} else {
  assert.deepEqual(result, { status: 'ok', version: 2 });
  assert.deepEqual(doc(1), { title: 'Mine', version: 2 });
}

